function resumeOrReport(ticketKey, customParams, config, stage, title, error) {
    var resume = feedbackLoop.resumeAgent({
        ticketKey: ticketKey,
        customParams: customParams,
        section: 'postAction',
        stage: stage,
        error: error.toString()
