            if (refreshed) return refreshed.pr;
            // Fallback: build minimal shape from URL if the SCM response differs.
            return buildFallbackPR(prResult, branchName);
        }
        console.warn('Could not create PR/MR:', prResult && prResult.error);
        return null;
