// and body edits, and post-merge edits never auto-close the issue (live
// 2026-10-17: PR #956 merged with 'Closes #952' added at the merge moment,
// #952 stayed OPEN).
var MERGE_QUEUE_LABELS = ['ai_validating'];

function isPrBodyFrozen(pr) {
   if (!pr || typeof pr !== 'object') return false;
   if (pr.merged === true) return true;
   var state = String(pr.state || '').toLowerCase();
   if (state === 'closed' || state === 'merged') return true;
   var labels = pr.labels || [];
   for (var i = 0; i < labels.length; i++) {
